//! Ownership regression test for `htm_conversion_options_visitor`.
//!
//! `htm_conversion_options_visitor` (crates/html-to-markdown-ffi/src/lib.rs, generated by
//! Alef) is documented to return an owned `*mut VisitorHandle` that the caller must release
//! with `htm_visitor_handle_free`. Its actual implementation is:
//!
//! ```ignore
//! match &obj.visitor {
//!     Some(val) => val as *const _ as *mut _,
//!     None => std::ptr::null_mut(),
//! }
//! ```
//!
//! `val` is a `&VisitorHandle` borrowed from the `Option` field embedded inside the
//! `ConversionOptions` struct — the cast changes the pointer's *type*, not its *provenance*.
//! The returned pointer still points at memory owned by the `ConversionOptions` allocation.
//! Calling `htm_visitor_handle_free` on it performs `Box::from_raw` on a pointer that was
//! never independently `Box`-allocated, which is an invalid free / use-after-free waiting to
//! happen the moment `htm_conversion_options_free` also runs. The generated sibling getter
//! `htm_conversion_options_update_visitor` (line ~3599) has the identical bug.
//!
//! This file cannot fix the bug (this crate's `src/` is Alef-generated and out of scope for
//! this change), but it proves the bug is real without ever executing the resulting
//! use-after-free/double-free: it asserts an ownership invariant that MUST hold for any
//! correctly "owned" getter (repeated calls return independently-allocated pointers) and
//! shows this getter violates it. The test is `#[ignore]`d with the reason recorded below so
//! CI stays green until the generator is fixed; running it explicitly
//! (`cargo test -- --ignored`) demonstrates the aliasing directly.

#![cfg(feature = "visitor")]
#![allow(unsafe_code)]

use std::ffi::{c_char, c_void};

use html_to_markdown_ffi::*;

#[allow(clippy::missing_const_for_fn)]
unsafe extern "C" fn noop_visit_text(
    _ctx: *const HtmContext,
    _user_data: *mut c_void,
    _text: *const c_char,
    _out_custom: *mut *mut c_char,
    _out_len: *mut usize,
) -> i32 {
    0 // HTM_VISIT_CONTINUE
}

/// SAFETY: see `ffi_panic_boundary_test::empty_callbacks` — an all-zero `HtmVisitorCallbacks`
/// is a valid "every callback is `None`" value.
#[allow(clippy::missing_const_for_fn)]
unsafe fn empty_callbacks() -> HtmVisitorCallbacks {
    unsafe { std::mem::zeroed() }
}

/// Documents and proves the aliasing bug without triggering the resulting UB: a correctly
/// "owned" getter must hand back a fresh, independently-freeable allocation on every call.
/// `htm_conversion_options_visitor` instead returns the SAME address every time, because it
/// is a type-punned borrow into the `ConversionOptions` struct, not a clone.
#[test]
#[ignore = "documents a known Alef-generated bug (crates/html-to-markdown-ffi/src/lib.rs:2610): \
            htm_conversion_options_visitor returns `&VisitorHandle as *mut VisitorHandle`, a \
            borrowed pointer typed as owned. Fix belongs in the alef generator/template, not \
            this hand-written test file. Un-ignore once the generator clones the handle."]
fn should_return_independently_owned_pointer_on_repeated_visitor_getter_calls() {
    unsafe {
        let mut callbacks = empty_callbacks();
        callbacks.visit_text = Some(noop_visit_text);
        let visitor = htm_visitor_create(&raw const callbacks);
        assert!(!visitor.is_null());

        let options = htm_conversion_options_default();
        htm_options_set_visitor(options, visitor);

        let first = htm_conversion_options_visitor(options);
        let second = htm_conversion_options_visitor(options);
        assert!(!first.is_null() && !second.is_null());

        // ~keep This is the correctness bar: an owned-handle getter must allocate a new,
        // ~keep independently-freeable clone on every call, exactly like every other ~60
        // ~keep getters in this file (e.g. `htm_html_metadata_document`, which clones).
        assert_ne!(
            first, second,
            "htm_conversion_options_visitor must return a freshly cloned handle on each call, \
             not alias the same underlying storage"
        );

        // Only reached once the generator is fixed: a real alloc -> use -> free cycle.
        htm_visitor_handle_free(first);
        htm_visitor_handle_free(second);
        htm_visitor_free(visitor);
        htm_conversion_options_free(options);
    }
}

/// Non-destructive proof of the SAME bug that does not require `#[ignore]`: it asserts the
/// buggy behaviour exactly as it exists today (pointer aliasing), so it stays green and acts
/// as a tripwire — if the generator is ever fixed to return distinct owned handles, this test
/// starts failing and must be deleted alongside un-ignoring the test above.
#[test]
fn should_alias_the_same_address_on_repeated_visitor_getter_calls_today() {
    unsafe {
        let mut callbacks = empty_callbacks();
        callbacks.visit_text = Some(noop_visit_text);
        let visitor = htm_visitor_create(&raw const callbacks);
        let options = htm_conversion_options_default();
        htm_options_set_visitor(options, visitor);

        let first = htm_conversion_options_visitor(options);
        let second = htm_conversion_options_visitor(options);
        assert!(!first.is_null() && !second.is_null());
        assert_eq!(
            first, second,
            "known bug: htm_conversion_options_visitor currently aliases the same address on \
             every call instead of cloning (crates/html-to-markdown-ffi/src/lib.rs:2610)"
        );

        // Free the underlying handle exactly ONCE, through the options struct's own free path,
        // never through `htm_visitor_handle_free(first)` — doing that would be the real,
        // reachable double free this test exists to document without triggering.
        htm_visitor_free(visitor);
        htm_conversion_options_free(options);
    }
}
